from lib import *
S = SS('s50')
steps = [
    step("Request.priority 必须是整数:种子页回调里依次构造优先级 0、5、-5、10**30、2.5、True、'7'、None 的请求——2.5、'7'、None 在构造 Request 时就抛 TypeError: Request priority not an integer(日志里没有错误,因为异常被我在生成器里 try 掉了;不 try 的话会变成回调异常);其余五个正常,True 当作 1。服务器收到的顺序是 10**30(r3)、5(r1)、True=1(r5)、0(r0)、-5(r2):负数排最后,超大整数也行。", t=tl(S(1)), mark=lidx(S(1), 'TypeError', '构造时报错'), done=lidx(S(1), '对应关系'), kv=KV([['整数 / 负数 / 超大整数 / True', '都可以'], ['浮点 / 字符串 / None', '构造 Request 时 TypeError'], ['顺序', '数值大的先出队']], ['浮点 / 字符串 / None'])),
    step("并发对“严格按优先级”的影响:一次产生 60 个随机优先级(0~9)的请求。出队本身严格按优先级,但服务器收到的顺序在并发高时会被网络竞争打乱:CONCURRENT_REQUESTS = 1、4 时逆序对数是 0(序列 9×10、8×8、7、6…),16 时 2 个,60 时 133 个(多个请求同时发出,到达服务器的先后不再受优先级控制)。逆序对数在不同次运行之间会变,这里是最后一次运行的值。结论:优先级决定谁先被取出,不保证谁先到达或先完成。", t=tl(S(2)), mark=lidx(S(2), '                    16 ', '                    60 '), done=lidx(S(2), '                     1 ', '                     4 '), b=bars([['并发 1', 0, '0'], ['并发 4', 0, '0'], ['并发 16', 2, '2'], ['并发 60', 133, '133']], 133, mark=[3], done=[0, 1, 2]), kv=KV([['并发 1 / 4', '逆序 0'], ['并发 16', '逆序 2'], ['并发 60', '逆序 133(多个同时发出,到达顺序不受控)']], ['并发 60'])),
    step("优先级只在“出队那一刻”比较队列里已有的请求:(a) 高优先级链 hi0 → hi1 → … → hi9(每个在上一个的响应之后才产生),和 10 个已排队的低优先级请求并发 1 一起跑,服务器收到 hi0, low9, hi1, low8, hi2, low7 … 交替出现——hi(n+1) 还没产生时引擎就先取了排队的 low,低优先级请求没有被饿死;(b) 10 个高优先级和 10 个低优先级同时排队,则 hi9 … hi0 全部先于 low9 … low0。所以“饿死”只发生在高优先级请求总是已经排在队里的时候。", t=tl(S(3)), mark=lidx(S(3), '(a)'), done=lidx(S(3), '(b)'), kv=KV([['链式产生的高优先级请求', '与排队的低优先级请求交替'], ['同时排好队', '高优先级全部先出队'], ['原则', '出队时只比较“当时已入队”的请求']], ['原则'])),
]
A = mkarts('s50', 50, 'Scrapy,Request.priority,调度器,优先级,真实验证,动画演示',
    '实测 Request.priority:必须是整数(浮点、字符串、None 构造时 TypeError,负数和 10**30 都行);出队严格按优先级但并发高时到达顺序会乱(并发 60 时 133 个逆序对);优先级只比较出队那一刻已排队的请求,链式产生的高优先级请求不会饿死排队的低优先级请求。',
    'priority 到底怎么影响请求的先后?能填什么值?并发高了还有效吗?高优先级请求会不会把低优先级的“饿死”?这篇用能记录到达顺序的服务器逐项量。',
    [('TypeError', '给 Request 传浮点、字符串或 None 作 priority 的结果'), ('0 → 133', '并发从 1 到 60 时,服务器收到顺序里的逆序对数(出队顺序本身仍按优先级)'), ('交替', '链式产生的高优先级请求与排队的低优先级请求的出队关系')],
    [('取值', '<p><code>priority</code> 只能是整数(<code>bool</code> 算整数),负数、很大的整数都可以;其它类型在构造 <code>Request</code> 时就抛 <code>TypeError</code>。</p>'),
     ('只管出队', '<p>优先级决定调度器先取哪个请求,不保证请求先到达服务器或先完成;并发越高,到达顺序越不受控。</p>'),
     ('只比较队列里的', '<p>每次出队只在已有的请求里挑优先级最高的。高优先级请求如果还没产生,就轮到低优先级的;只有高优先级请求一直排在队里,低优先级的才会等待。</p>')],
    steps,
    [ENV_Y + '。种子页的回调里一次产生所有请求,保证它们同时在队列里再出队;到达顺序来自本机线程服务器的日志,并发较高时同时发出的请求到达顺序有竞争(逆序对数每次运行不同)',
     '没有验证:Request.priority 与 DownloaderAwarePriorityQueue 多域名的组合(见调度队列那一篇:优先级只在域名内有效);priority 在 JOBDIR 磁盘队列里的持久化;RETRY_PRIORITY_ADJUST、REDIRECT_PRIORITY_ADJUST 与 DEPTH_PRIORITY 叠加的最终值;优先级取值的上下限(Python 整数无上限,磁盘队列的目录名用优先级,没有测极大值)'],
    '请求优先级')
